variables.code:
-- SQL:2023 Standard doesn't have imperative variables.
-- Standard uses DECLARE for cursors or inside standard PSM (Persistent Stored Modules)
DECLARE v_counter INT DEFAULT 0;

data_types.code:
CREATE TABLE example (
  id INTEGER PRIMARY KEY,
  name VARCHAR(50),
  price DECIMAL(10, 2),
  is_active BOOLEAN
);

operators.code:
SELECT a + b, a - b, a * b, a / b
FROM numbers
WHERE a = b AND c <> d OR e IS NOT NULL;

while_loop.code:
-- SQL/PSM Standard While Loop
WHILE v_counter < 10 DO
  SET v_counter = v_counter + 1;
END WHILE;

functions.code:
CREATE FUNCTION add_numbers (a INT, b INT)
RETURNS INT
BEGIN
  RETURN a + b;
END;

arrays.code:
CREATE TABLE array_data (
  id INT,
  tags TEXT ARRAY
);

error_handling.code:
DECLARE EXIT HANDLER FOR SQLEXCEPTION
BEGIN
  ROLLBACK;
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An error occurred';
END;

range.code:
SELECT * FROM orders 
WHERE order_date BETWEEN '2024-01-01' AND '2024-12-31'
LIMIT 10 OFFSET 20;

iterators.code:
-- Window row iteration
SELECT id, ROW_NUMBER() OVER (ORDER BY created_at) AS row_num
FROM logs;

oop_classes.code:
CREATE TABLE users (
    id INT PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

